n = int(input())
stock = {}
for _ in range(n):
    command, name, amount = input().split()
    amount = int(amount)
    if command == "ADD":
        stock[name] = stock.get(name, 0) + amount
    else:
        if stock.get(name, 0) >= amount:
            stock[name] -= amount
        else:
            print("부족", name)

left = False
for name in sorted(stock):
    if stock[name] > 0:
        print(name, stock[name])
        left = True
if not left:
    print("재고 없음")

