# 독서 마라톤: READ는 읽은 쪽수를 더하고, ASK는 누적 쪽수를 알려줘요.
n = int(input())
pages = {}
for _ in range(n):
    parts = input().split()
    command = parts[0]
    name = parts[1]
    if command == "READ":
        # 처음 보는 이름은 0쪽에서 시작해요.
        pages[name] = pages.get(name, 0) + int(parts[2])
    else:
        # 기록이 없는 이름도 오류 없이 0쪽으로 알려줘요.
        print(pages.get(name, 0))
